// Circuit track-layout images (local SVGs in /public/circuits)
// Generated by scripts/generate-circuit-svgs.mjs from bacinger/f1-circuits (MIT)
import { getCircuitId } from "./circuit-data";

export const AVAILABLE_CIRCUIT_MAPS = new Set([
  "albert_park", "americas", "bahrain", "baku", "catalunya", "hockenheimring",
  "hungaroring", "imola", "interlagos", "istanbul", "jeddah", "losail",
  "madring", "marina_bay", "miami", "monaco", "monza", "mugello",
  "nurburgring", "portimao", "red_bull_ring", "ricard", "rodriguez",
  "sepang", "shanghai", "silverstone", "sochi", "spa", "suzuka", "vegas",
  "villeneuve", "yas_marina", "zandvoort",
]);

/**
 * Returns the local track map for a circuit, or null when we don't have one.
 * Prefers the Ergast circuitId; falls back to matching the circuit name.
 */
export function getCircuitImageUrl(
  circuitName: string,
  circuitId?: string
): string | null {
  const id = circuitId || getCircuitId(circuitName);
  if (!id || !AVAILABLE_CIRCUIT_MAPS.has(id)) return null;
  return `/circuits/${id}.svg`;
}
